const purchase = $('Extract Purchase Data').first().json;
const members = $('Read Current Points').all();

const earnedPoints = Math.floor(parseFloat(purchase.orderTotal));
const member = members.find(m => m.json['Customer ID'] === purchase.customerId);

const previousPoints = member ? parseInt(member.json['Total Points'] || 0) : 0;
const previousTier = member ? (member.json.Tier || 'Bronze') : 'Bronze';
const newTotalPoints = previousPoints + earnedPoints;

let newTier = 'Bronze';
if (newTotalPoints >= 5000) newTier = 'Platinum';
else if (newTotalPoints >= 2000) newTier = 'Gold';
else if (newTotalPoints >= 500) newTier = 'Silver';

const tierUpgraded = newTier !== previousTier && 
  ['Silver', 'Gold', 'Platinum'].indexOf(newTier) > ['Silver', 'Gold', 'Platinum'].indexOf(previousTier);

const tierBenefits = {
  Bronze: 'Earn 1 point per $1',
  Silver: '1.5x points + free shipping',
  Gold: '2x points + free shipping + early access',
  Platinum: '3x points + free shipping + early access + personal shopper'
};

return [{
  json: {
    customerId: purchase.customerId,
    customerName: purchase.customerName,
    customerEmail: purchase.customerEmail,
    orderId: purchase.orderId,
    orderTotal: purchase.orderTotal,
    earnedPoints,
    previousPoints,
    newTotalPoints,
    previousTier,
    newTier,
    tierUpgraded,
    tierBenefits: tierBenefits[newTier],
    isNewMember: !member,
    updatedAt: new Date().toISOString()
  }
}];

const members = $input.all();
const tierCounts = { Bronze: 0, Silver: 0, Gold: 0, Platinum: 0 };
let totalPoints = 0;

for (const m of members) {
  const tier = m.json.Tier || 'Bronze';
  tierCounts[tier] = (tierCounts[tier] || 0) + 1;
  totalPoints += parseInt(m.json['Total Points'] || 0);
}

const summary = `Total Members: ${members.length}\nBronze: ${tierCounts.Bronze}\nSilver: ${tierCounts.Silver}\nGold: ${tierCounts.Gold}\nPlatinum: ${tierCounts.Platinum}\nTotal Points Issued: ${totalPoints}`;

return members.map(m => ({
  json: {
    email: m.json.Email,
    name: m.json.Name || 'Valued Customer',
    points: m.json['Total Points'] || 0,
    tier: m.json.Tier || 'Bronze',
    monthlySummaryText: summary
  }
}));
